mod solution;

fn main() {
    let cases = [
    (r#"text=abracadabra pattern=abra"#, r#"0,7"#),
    (r#"text=aaaa pattern=aa"#, r#"0,1,2"#),
    (r#"
text=aaaa pattern=aa
"#, r#"0,1,2"#),
    (r#"  
text=abracadabra pattern=abra
  "#, r#"0,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS rabin-karp");
}
